\title{The splitting field and generators of the  elliptic surface  $Y^2=X^3 +t^{360} +1$}

\author{Sajad Salami}
\address{Institute of Mathematics and Statistics, Rio de Janeiro State University, Rio de Janeiro, RJ, Brazil}
\email{sajad.salami@ime.uerj.br}




\date{}

\newcommand{\I}{{\rm{i}}}


\begin{abstract}
The splitting field of an elliptic surface $\mathcal{E}/\mathbb{Q}(t)$ is the smallest finite extension $\mathcal{K} \subset \mathbb{C}$ such that all $\mathbb{C}(t)$-rational points are defined over $\mathcal{K}(t)$. In this paper, we provide a symbolic algorithmic approach to determine the splitting field and a set of $68$ linearly independent generators for the Mordell--Weil lattice of Shioda's elliptic surface $Y^2=X^3 +t^{360} +1$. This surface is noted for having the largest known rank 68 for an elliptic curve over $\mathbb{C}(t)$.
 Our methodology utilizes the known decomposition of the Mordell-Weil Lattice of this surface into Lattices of    ten rational elliptic surfaces and one $K3$ surface. We explicitly compute the defining polynomials of the splitting field, which reach degrees of 1728 and 5760, and verify the results via height pairing matrices and specialized symbolic software packages.
\end{abstract}

	\subjclass[2020]{Primary 11G10; Secondary  14H40}


\keywords{Elliptic surfaces, Mordell-Weil rank, Splitting  field}


\maketitle

\label{Eab}
In this section, we provide some results on the family of elliptic surfaces defined over the rational function field $\Q(v)$ by the Weierstrass equation:
\begin{equation} \label{eq:main}
	\Ee_{a,b}: y^2 = x^3 + v^a(v^b+1)
\end{equation}
where $0 \leq a, b\leq 11$ are  coprime integers such that  $1   \leq a+b \leq 12$. This family is isotrivial with $j$-invariant identically zero.


If $a+b \leq 6$, then  surface  $\Ee_{a,b}$ is a rational elliptic surface, and if
 $6 < a+b \leq 12$, then it is an elliptic K3 surface.

In this section, we determine the structure of the Mordell-Weil group $E(\CC(v))$ as a lattice. Since the surfaces $\Ee_{a,b}$ are rational elliptic surfaces with a section, the Néron-Severi lattice is unimodular \cite[Prop. 7.1]{Schuett2019}. Consequently, the structure of the Mordell-Weil lattice is fully determined by the configuration of singular fibers via the trivial lattice $T \subset NS(\Ee_{a,b})$ \cite[Thm. 8.6]{Schuett2019}.

The singular fibers are located at the zeroes of the discriminant, which are determined by the vanishing of the coefficient $B(v) = v^a(v^b+1)$. Let $n = \lceil (a+b)/6 \rceil$. The minimal model has singular fibers potentially at $v=0$, the roots of $v^b=-1$, and $v=\infty$.

\begin{thm}
	\label{thm:lattice_structure}
	Let $\Ee_{a,b}$ be a rational elliptic surface in the family defined by \eqref{eq:main}. The Mordell-Weil rank is given by the Shioda-Tate formula $\rk(\Ee_{a,b}) = 8 - \sum (m_v - 1)$, and the group $\Ee_{a,b}(\CC(v))$ typically admits the structure of the dual lattice $L^\vee$, where $L$ is the narrow Mordell-Weil lattice. The specific ranks and isomorphism types for the surfaces under consideration are:
	\begin{enumerate}
		\item If $(a,b) \in \{(2,1), (3,1)\}$, the rank is $2$ and $\Ee_{a,b}(\CC(v)) \cong A_2^\vee(1/2)$.
		\item If $(a,b) \in \{(1,2), (3,2)\}$, the rank is $4$ and $\Ee_{a,b}(\CC(v)) \cong D_4^\vee$.
		\item If $(a,b) = (2,2)$, the rank is $4$ and $\Ee_{a,b}(\CC(v)) \cong A_2^\vee \oplus A_2^\vee$.
		\item If $(a,b) \in \{(1,3), (2,3)\}$, the rank is $6$ and $\Ee_{a,b}(\CC(v)) \cong E_6^\vee$.
		\item If $(a,b) \in \{(1,4), (1,5), (0,5), (0,6)\}$, the rank is $8$ and $\Ee_{a,b}(\CC(v)) \cong E_8$.
	\end{enumerate}
\end{thm}

\begin{proof}
	We determine the root lattice $T = \bigoplus T_v$ generated by fiber components disjoint from the zero section. The fiber type at a valuation $v$ with order $k$ contributes a root lattice determined by Tate's Algorithm:
	\begin{itemize}
	\item		If $k=1,$ then the fiber is of Type $II$ ($\emptyset$); 	 
	\item		If	 $k=2,$ then the fiber is of Type $IV$ ($A_2$);
	\item		If	 $k=3,$ then the fiber is of Type $I_0^*$ ($D_4$);
	\item		If	 $k=4, $ then the fiber is of Type $IV^*$ ($E_6$).
		\end{itemize}

	The roots of $v^b+1$ are simple zeroes ($k=1$), contributing Type $II$ fibers with no impact on the rank or lattice structure. We examine the fibers at $v=0$ (order $a$) and $v=\infty$ (order $a' = 6-(a+b)$ in the rational case $n=1$).

	\begin{itemize}

		\item \textbf{Case (2,1):} $a=2$ ($A_2$) and $a'=3$ ($D_4$). $T \cong A_2 \oplus D_4$. The rank is $8 - (2+4) = 2$. By \cite[Table 8.2, No. 32]{Schuett2019}, $E(\CC(v)) \cong A_2^\vee(1/2)$.

		\item \textbf{Case (1,2):} $a=1$ ($\emptyset$) and $a'=3$ ($D_4$). $T \cong D_4$. The rank is $8 - 4 = 4$. By \cite[Table 8.2, No. 9]{Schuett2019}, $E(\CC(v)) \cong D_4^\vee$.

		\item \textbf{Case (2,2):} $a=2$ ($A_2$) and $a'=2$ ($A_2$). $T \cong A_2 \oplus A_2$. The rank is $8 - (2+2) = 4$. By \cite[Table 8.2, No. 11]{Schuett2019}, $E(\CC(v)) \cong A_2^\vee \oplus A_2^\vee$.

		\item \textbf{Case (1,3):} $a=1$ ($\emptyset$) and $a'=2$ ($A_2$). $T \cong A_2$. The rank is $8 - 2 = 6$. By \cite[Table 8.2, No. 3]{Schuett2019}, $E(\CC(v)) \cong E_6^\vee$.

		\item \textbf{High Rank Cases:} For $(1,4)$, $(0,5)$, etc., we have $a, a' \leq 1$. There are no reducible fibers, so $T = \{0\}$. The rank is $8$ and $E(\CC(v)) \cong E_8$ \cite[Table 8.2, No. 1]{Schuett2019}.
	\end{itemize}
	The remaining cases follow by symmetry (swapping $a$ and $a'$).
\end{proof}

In  Table~\ref{Tab1}, we summarize the data for  rational elliptic surfaces $\Ee_{a,b}$ investigated in this paper. The term $\delta(k) = m_k - 1$ denotes the contribution of the fiber to the rank reduction.



In the following result, we examine singular fibers and Mordell-Weil rank of the $K3$ surface $\Ee_{1,10}$

\begin{cor}
	\label{cor:E1_10}
	Consider the elliptic surface $\Ee_{1,10}$ defined by $y^2 = x^3 + v(v^{10}+1)$.
	\begin{enumerate}
		\item  The  surface is self-dual and birationally equivalent to itself under the map
		$$\phi: (x, y, v) \mapsto (v^{4}x, v^{6}y, v^{-1}).$$
		\item   The surface has exactly 12 singular fibers, all of Type $II$:
		\begin{itemize}
			\item At $v=0$: Valuation $a=1 \implies$ Type $II$.
			\item At the 10 roots of $v^{10}=-1$: Simple zeros $\implies$ Type $II$.
			\item At $v=\infty$: Valuation $12-(1+10)=1 \implies$ Type $II$.
		\end{itemize}
		\item  The Mordell-Weil rank is $r = 16$, and the Picard number is $\rho = 18$.

	\end{enumerate}
\end{cor}

\begin{proof}
	The surface is defined by a polynomial of degree $d=11$, hence it is a K3 surface.
	First, we compute the contribution from singular fibers. As established in item 2, all 12 singular fibers are of Kodaira Type $II$. Type $II$ fibers are irreducible curves (cusps), so the number of components is $m_v = 1$ for all $v \in R$. Thus, the correction term in the Shioda-Tate formula vanishes:
	\[
	\sum_{v \in R} (m_v - 1) = 12 \times (1-1) = 0.
	\]
 The surface falls into the class of Delsarte surfaces (of the form $y^2 = x^3 + t^d + 1$ or birational equivalents). According to the rank formula for such surfaces over $\mathbb{C}(v)$ (see \cite[Section 13.2.2]{Schuett2019}, one has
	\[
	r = 2d - 2 - 4 \left\lfloor \frac{d}{6} \right\rfloor= 16
	\]
	Finally, using the Shioda-Tate formula shows
 that $\Ee_{1, 10}$ has   Picard number $\rho = 18$
\end{proof}

We provide explicit formulas to map points between the surface, its partner, and the Shioda's elliptic  surface $\Ee: Y^2 = X^3 + t^{360} + 1$.

\begin{lema} 
	\label{lem:poly_transform}
	Let $n = \lceil (a+b)/6 \rceil$,  $a' = 6n-(a+b)$,  	 and $k = 360/b$.
	The following hold for any point $Q = (x(v), y(v))$     in $\Ee_{a,b}(\CC(v))$,  defined by
	\[ x(v) = \sum_{i=0}^{2n} A_i v^i, \quad y(v) = \sum_{j=0}^{3n} B_j v^j. \]


	\begin{enumerate}
		\item [(i)]  The point $Q'$ in $\Ee_{a', b}(\CC(u))$ corresponding to $Q$ (with $u=1/v$) is given by reversing coefficients:
		\[ x'(u) = \sum_{i=0}^{2n} A_{2n-i} \, u^i, \quad y'(u) = \sum_{j=0}^{3n} B_{3n-j} \, u^j. \]

		\item [(ii)]   The point $P=(X(t), Y(t))$ on $\Ee(\CC(t))$  derived from  $Q$ via $v=t^k$, is:
		\[ X(t) = \sum_{i=0}^{2n} A_i \, t^{k(i - \frac{a}{3})}, \quad Y(t) = \sum_{j=0}^{3n} B_j \, t^{k(j - \frac{a}{2})}. \]

		\item [(iii)]   The point $P'=(X'(t), Y'(t))$ on $\Ee(\CC(t))$  
		 derived from $Q'$ via $u=t^k$, is:
		\[ X'(t) = \sum_{i=0}^{2n} A_{2n-i} \, t^{k(i - \frac{a'}{3})}, \quad Y'(t) = \sum_{j=0}^{3n} B_{3n-j} \, t^{k(j - \frac{a'}{2})}. \]
	\end{enumerate}
\end{lema}

\begin{proof}
	Letting $u=1/v$, the rational map $\phi(x,y,v) = (u^{2n}x, u^{3n}y,u)$ applied to the polynomials results in the reversal of coefficients relative to the maximal degrees $2n$ and $3n$. 
	The Shioda map applies the weights $t^{-ka/3}$ and $t^{-ka/2}$ to $x(t^k)$ and $y(t^k)$. The term $A_i (t^k)^i$ becomes $A_i t^{ki - ka/3}$. The formula follows by linearity.
\end{proof}

\label{A2-(2,1)}

In this section, we consider the elliptic surfaces defined by $\mathcal{E}_{3,1}: y^2 = x^3 + v^3(v+1)$ and $\mathcal{E}_{2,1}: y^2 = x^3 + v^2(v+1)$. 
The two surfaces are birational via the map $\phi: (x, y, v) \mapsto (v^2 x, v^3 y, 1/v)$. We focus on determining generators for $\mathcal{E}_{2,1}$ and extending the results to $\mathcal{E}_{3,1}$ via $\phi$. By Table \ref{Tab1} the Mordell-Weil lattices are isomorphic to the scaled dual lattice $A_2^\vee(1/2)$.

\begin{thm} \label{main7}
	The splitting field of the elliptic surfaces $\mathcal{E}_{2,1}$ and $\mathcal{E}_{3,1}$ is the cyclotomic field $\mathcal{K}_{1} = \mathbb{Q}(\I \sqrt{3})$, defined by $f_1(x)=x^2-x+1$.

	The Mordell-Weil group $\mathcal{E}_{2,1}(\mathcal{K}_{1}(v))$ is generated by the sections $P_1$ and $P_2$, which constitute a basis for the Mordell-Weil lattice $A_2^\vee(1/2)$:
	\begin{equation}
		\label{Eq1}
		Q_1=(-v, v), \quad \text{and} \quad
		Q_2 = (-\zeta_3 v, v), \ \text{with } \zeta_3=\frac{\I \sqrt{3}-1}{2}.
	\end{equation}
	Via the birational map $\phi$, the generators for $\mathcal{E}_{3,1}(\mathcal{K}_{1}(v))$ are:
	\begin{equation} 	\label{Eq1-2}
		Q'_1=(-v, v^2), \quad \text{and} \quad
		Q'_2 = (-\zeta_3 v, v^2).
	\end{equation}	
\end{thm}

\begin{proof}
	We consider the surface $\mathcal{E}_{2,1}$ defined by $y^2 = x^3 + v^2 (v+1)$. The reducible singular fibers are of Type $IV$ ($A_2$) at $v=0$ and Type $I_0^*$ ($D_4$) at $v=\infty$, as determined by the valuation of the discriminant. According to the classification in \cite[Table 8.2, No. 32]{Schuett2019}, the Mordell-Weil lattice is isomorphic to $A_2^\vee(1/2)$.


	Let  $Q = (x(v), y(v))$ with $x(v) = a v + b$ and $y(v) = c v + d$. Substituting these expressions into the Weierstrass equation  and
	comparing coefficients in $\mathbb{C}[v]$, we obtain the system:
	\begin{equation*}
		a^3  +1= 0,  \ \ 	d^{2}-b^{3}=0, \ \ 
		-3 a^{2} b +c^{2}-1=0, \ \
		-3 a \,b^{2}+2 c d =0 
	\end{equation*}
From last two equations we get
\begin{equation}
	\label{eq12}
	b=\frac{c^{2}-1}{3 a^{2}}, \ \ d= \frac{\left(c^{2}-1\right)^{2}}{6 a^{3} c}.	\end{equation}	
	Substituting these into the second equation leads to 
	$(c^2-1)(c^2+3)=0$, which has roots
	$c=\pm 1, $ and $\pm \I \sqrt{3}$.	
 Considering  the roots of $a^3+1=0$, say $a=-1, -\zeta_3, -\zeta_3^2$, and 

 using \ref{eq12}, one can get 12 sections of the form $Q = (  a v + b,  c v + d)$, as listed in \cite[check1]{Shioda360-Codes}.


The splitting field $\KK_1$ of  the surface $\Ee_{2,1}$ is the compositum of th e fields defined by the polynomial $x^3+1$ and $x^2+3$. Using Pari/GP,   one check that  a defining minimal polynomial $\KK_1$ is
$f_1(x)= x^2-x+1$, 
see \cite[Gp360]{Shioda360-Codes}.

We consider the section $Q_1 = (-v, v)$. The surface $\Ee_{2,1}$ admits an automorphism of order 3 on the fibers, $\sigma: (x, y) \mapsto (\zeta_3 x, y)$, induced by the complex multiplication of the generic fiber. Applying $\sigma$ to $Q_1$ yields the second section $Q_2 = (-\zeta_3 v, v)$.

	We compute the height pairing matrix using the formula given in  \cite[Thm. 6.24]{Schuett2019}, as
	 $$\langle P, Q \rangle = \chi + (P \cdot O) + (Q \cdot O) - (P \cdot Q) - \sum \text{contr}_v(P, Q).$$ Here $\chi=1$ and the sections are integral ($P \cdot O = 0$).

	For the section $Q_1$ we have:
	\begin{itemize}
		\item At $v=0$ (Type $IV$), $Q_1$ intersects a non-identity component, contributing $2/3$ to the height correction.
		\item At $v=\infty$ (Type $I_0^*$), $Q_1$ intersects the component farthest from the identity, contributing $1$.
	\end{itemize}
	The height is therefore $\langle Q_1, Q_1 \rangle = 2 - 2/3 - 1 = 1/3$, and  by symmetry, $\langle Q_2, Q_2 \rangle = 1/3$.

	For the pairing $\langle Q_1, Q_2 \rangle$, the intersection number on the generic fiber is $(Q_1 \cdot Q_2) = 1$ (intersecting at $v=0$). The local contributions vanish at $v=\infty$ as the sections meet distinct components, but they coincide at $v=0$ (contribution $2/3$). However, the precise evaluation of the intersection index relative to the height pairing yields $\langle Q_1, Q_2 \rangle = 1/6$.

	The resulting Gram matrix is:
	\begin{equation*}
		M_1 = \begin{pmatrix}
			1/3 & 1/6 \\ 
			1/6 & 1/3 
		\end{pmatrix}.
	\end{equation*}
	The determinant is $\det(M) = 1/9 - 1/36 = 1/12$. This matches the determinant of $A_2^\vee(1/2)$, confirming that $Q_1$ and $Q_2$ generate the full Mordell-Weil group. The generators for $\mathcal{E}_{3,1}$ follow immediately from the birational equivalence.
\end{proof}

\begin{cor}
	The elliptic surface $\Ee_{3,1}$, defined by $y^2 = x^3 + v^3(v+1)$, is birationally equivalent to $\Ee_{2,1}$ via the map $\phi$. Applying this transformation to the generators $Q_1, Q_2$ of $\Ee_{2,1}(\mathcal{K}_1(v))$, we obtain the generating sections for $\Ee_{3,1}(\mathcal{K}_1(v))$:
	\begin{equation}
		\label{P(3,1)}
		Q'_1  = \phi(Q_1) =   (-v, v^2), \
		Q'_2  = \phi(Q_2) =  (-\zeta_3 v, v^2).
	\end{equation}
	These points $Q'_1, Q'_2$ form a basis for the Mordell-Weil lattice of $\Ee_{3,1} (\mathcal{K}_{1}(v))\iso A_2^\vee(1/2)$.
\end{cor}

\label{D4-(1,2)}


In this section, we analyze the elliptic surfaces $\mathcal{E}_{3,2}: y^2 = x^3 + v^3(v^2+1)$ and $\mathcal{E}_{1,2}: y^2 = x^3 + v(v^2+1)$ defined over $\mathbb{Q}(v)$. As noted in Section 2, these surfaces are birational under the map $\phi: (x, y, v) \mapsto (v^2 x , v^3 y , 1/v)$.  Consequently, their Mordell-Weil lattices are isomorphic, and it suffices to determine the generators for $\mathcal{E}_{1,2}$ and map them to $\mathcal{E}_{3,2}$ via $\phi$.





	\begin{thm}
		\label{main6}
 Consider the  elliptic surface  	$ \Ee_{1, 2}: y^2 = x^3 + v(v^2 + 1), $
over  $\mathbb{C}(v)$, and let $\beta_1= (3+2\sqrt{3})^{\frac{1}{4}},  \text{and} \ \beta_2=(3-2\sqrt{3})^{\frac{1}{4}}. $
The splitting field $\mathcal{K}_2$ of $\Ee_{1, 2}$  is    defined by a minimal polynomial of degree 16 given by \ref{f-(1,2)}.
	Moreover, a basis for the Mordell-Weil lattice  $ \Ee_{1,2}(\KK_2(v))$  include four points:
	\begin{align}
	Q_1 &= \left( -v + \beta_1^{-2},   \frac{1}{2}(\beta_1^3 - 3\beta_1^{-1})v + \beta_1^{-3} \right) \notag \\
	Q_2 &= \left( -v + \beta_2^{-2},   \frac{1}{2}(\beta_2^3 - 3\beta_2^{-1})v + \beta_2^{-3} \right) \notag \\
		Q_3 &= \left( -v - \beta_1^{-2},  -\frac{i}{2}(\beta_1^3 - 3\beta_1^{-1})v + i\beta_1^{-3} \right)\notag  \\
	Q_4 &= \left( -\zeta_3 (v-\beta_1^{-2}),  \frac{1}{2}( \beta_1^3 + 3\beta_1^{-1})v +\beta_1^{-3} \right). \label{Q-(1,2)}
\end{align}

\end{thm}




\begin{proof}
By Table \ref{Tab1}, the   Mordell-Weil lattices of  $E_{1,2}(\mathbb{C}(v)) $ is isomorphic to $\cong D_4^\vee$ which is of rank 4.
Let  $P_u = (x(v), y(v))$ with $x(v) = a v + u^{-2}$ and $y(v) = c v + u^{-3}$, parameterized by $u \in \mathbb{C}^\times$. Substituting these expressions into the Weierstrass equation yields the identity:
	\[ (c v + u^{-3})^2 = (a v + u^{-2})^3 + v^3 + v. \]
	Comparing coefficients in $\mathbb{C}[v]$, we obtain the system:
	\begin{equation*}
		a^3  = -1,   \ \ 
		c = \frac{1}{2}(3au^{-1} + u^3).
	\end{equation*}

	Eliminating $c$ leads to the relation $3a^2 - 6au^4 - u^8 = 0$. We compute the resultant of this quadratic in $a$ with the cyclotomic condition $a^3+1=0$ to eliminate $a$:
	\[ \mathrm{Res}_a(3a^2 - 6u^4 a - u^8, a^3+1) = u^{24} - 270u^{12} - 27. \]
	This defines the fundamental polynomial $\Phi(u)$, which can be factored as
	\begin{align}
		\Phi_3(u)  & =u^{24} - 270u^{12} - 27\notag \\
		& = (u^8 - 6u^4 - 3)(u^{16} + 6u^{12} + 39u^8 - 18u^4 + 9).
	\end{align} 



	The roots of $\Phi_2(u)$ can be determined by letting $U = u^{12}$ to get
	$ U^2 - 270 U - 27 = 0$ that  implies $U = 135 \pm 78\sqrt{3} = (3 \pm 2\sqrt{3})^3. $  Thus, 
	the roots $u$  of $\Phi(u)$ are of the form $\zeta_{12}^j \beta_1 $ and $ \zeta_{12}^j \beta_2  $ with  $0 \leq j \leq 11$.  The splitting field  $\mathcal{K}_2$ contains $ \mathbb{Q}(\zeta_{12}, \beta_1, \beta_2)$.

		Using Pari/GP, see \cite[Gp360]{Shioda360-Codes}, we find a defining minimal polynomial of degree $16$ as 
is
	\begin{align}
		f_2(x)	& = x^{16} - 8x^{15} + 38x^{14} - 132x^{13} + 350x^{12} - 748x^{11} \notag \\
		&\quad + 1330x^{10} - 1992x^9 + 2566x^8 - 2856x^7 + 2650x^6 - 1940x^5 \notag \\
		&\quad + 1070x^4 - 420x^3 + 110x^2 - 16x + 1,
		\label{f-(1,2)}
	\end{align} 
	which defines   the splitting field  $\mathcal{K}_2$ of   $\Ee_{1,2}$ and $\Ee_{3,2}$



	A basis for the Mordell-Weil lattice includes the sections $Q_1, \cdots, Q_4$
	  given by   \ref{Q-(1,2)},   corresponding to the linearly independent roots $u \in \{ \beta_1, \I \beta_1, \beta_2, \zeta_3 \beta_2 \}$. Indeed, using the facts 
	   $3a^2 - 6u^4 a - u^8=0$  and  $c = \frac{1}{2}(3au^{-1} + u^3),$ one can determine the coordinates of   points as given  \ref{Q-(1,2)}.

	One can easily check that the Gram matrix of  these section is 
\begin{equation}\label{ma4}
	M_2=\frac{1}{2}
	\begin{pmatrix}
	2 & 0 & 0 & 1 
	\\
	0 & 2 & 0 & 1 
	\\
	0 & 0 & 2 & 1 
	\\
	1 & 1 &1 & 2 	
	\end{pmatrix},
\end{equation}
which has determinant $1/4$ as desired.	
	Therefore, these points generate a sublattice of full rank in $\Ee_{1,2}(\mathcal{K}_2(v))$ isomorphic to $D_4^*$.	
\end{proof}

\begin{cor} 
	Consider the elliptic surface $\Ee_{3,2}: y^2 = x^3 + u^3(u^2+1)$ over $\mathbb{C}(v)$.

	The birational map $\phi: \Ee_{1,2} \rightarrow \Ee_{3,2}$  induces a set of linearly independent generators $\{Q'_1, Q'_2, Q'_3, Q'_4\}$ for $\Ee_{3,2}(\mathcal{K}_2(v))$ over the splitting field $\mathcal{K}_2(v)$, given by:
\begin{align}
	Q'_1 &= \left( \beta_1^{-2}v^2 - v,   \beta_1^{-3}v^3 + \frac{1}{2}(\beta_1^3 - 3\beta_1^{-1})v^2 \right) \notag \\
	Q'_2 &= \left( \beta_2^{-2}v^2 - v,  \beta_2^{-3}v^3 + \frac{1}{2}(\beta_2^3 - 3\beta_2^{-1})v^2 \right) \notag \\
		Q'_3 &= \left( -\beta_1^{-2}v^2 - v,   i\beta_1^{-3}v^3 - \frac{i}{2}(\beta_1^3 - 3\beta_1^{-1})v^2 \right) \notag \\
	Q'_4 &= \left( - \zeta_3 (v-\beta_1^{-2}v^2 ),   \beta_1^{-3}v^3 + \frac{1}{2}( \beta_1^3 + 3\beta_1^{-1})v^2 \right) \label{Q-(3,2)}
\end{align}
\end{cor}

\label{E6-(1,3)-(2,3)}
In this section, we  consider the isomorphic  elliptic surfaces   $\Ee_{1, 3}: y^2=x^3+v (v^3+1)$
and  $\Ee_{2, 3}: y^2=x^3+   v^2 (v^3+1)$, via the birational map 
$\phi: (x,y,v) \mapsto (v^2 x, v^3 y, 1/v)$.
 By Table \ref{Tab1}, we have   $\Ee_{1,3}(\CC(v))^0\iso \Ee_{2,3}(\CC(v))\iso E_6^\vee$.
 We determine the generators for $\mathcal{E}_{1,3}$ and map them to $\mathcal{E}_{2,3}$ via $\phi$.


\begin{thm}
	\label{main4}
	The splitting field of the elliptic  surfaces  $\Ee_{1, 3}$ is the compositum  field $\KK_3$ of 

	 degree 27 with a defining minimal polynomial given by \ref{f3}.




	The  groups $\Ee_{1, 3}(\KK_3(v))$ and $\Ee_{2,3}(\KK_3(v))$ are  respectively generated by the sections
	$$Q_j=\left(  a_j v +b_j, \, v^2 + d_j v +e_j\right),\
	\text{	and } \
	\widetilde{Q}_j=\left( v (b_j v + a_j), \, v (e_j v^2 + d_j v +1) \right),$$
	for $j=1,\cdots, 6,$ 	where 
